367	// Records that have never been processed, and terminal records, expose no
368	// retry time; the six states are distinguishable via query.
369	func TestPendingNeverProcessed(t *testing.T) {
370		q, _ := openTempQueue(t)
371		defer q.Close()
372		q.RegisterSource("a")
373		q.Submit(env("m", "a", "b", 1, 10, 0))
374		if q.Now() != 0 {
375			t.Fatalf("new queue must report never-advanced time 0")
376		}
