573	// Corruption before the final frame is fatal; a torn final frame is truncated.
574	func TestMidLogCorruptionAndTornTail(t *testing.T) {
575		dir := t.TempDir()
576		q, err := Open(dir)
577		if err != nil {
578			t.Fatal(err)
579		}
580		q.RegisterSource("a")
581		q.Submit(env("m1", "a", "b", 1, 10, 0))
582		q.Submit(env("m2", "a", "b", 2, 10, 0))
583		q.Close()
584	
585		raw, err := os.ReadFile(filepath.Join(dir, logName))
586		if err != nil {
587			t.Fatal(err)
588		}
589	
590		// Torn tail: cut the last frame in half; reopen truncates and keeps m1.
591		torn := make([]byte, len(raw)-3)
592		copy(torn, raw)
593		tornDir := t.TempDir()
594		os.WriteFile(filepath.Join(tornDir, logName), torn, 0o600)
595		qt, err := Open(tornDir)
596		if err != nil {
597			t.Fatalf("torn tail should truncate and open: %v", err)
598		}
599		if _, ok := qt.Query("m1"); !ok {
600			t.Fatalf("m1 should survive torn-tail recovery")
601		}
602		if _, ok := qt.Query("m2"); ok {
603			t.Fatalf("partial m2 frame must be dropped")
604		}
605		qt.Close()
606	
607		// Flip a byte inside the middle frame (m1 body): checksum mismatch that is
608		// not at EOF must be fatal.
609		bad := append([]byte(nil), raw...)
610		pos := len(logMagic)
611		// Flip a byte inside the JSON body of the first frame (the version frame).
612		bad[pos+4+2] ^= 0xFF
613		badDir := t.TempDir()
614		os.WriteFile(filepath.Join(badDir, logName), bad, 0o600)
615		if _, err := Open(badDir); !errors.Is(err, ErrCorrupt) {
616			t.Fatalf("mid-log corruption must be ErrCorrupt, got %v", err)
617		}
618	}
