950		if q.headers["a"].trusted == nil || q.headers["a"].trusted.Height != 100 ||
951			q.headers["a"].trusted.Root != "0x100" {
952			t.Fatalf("accepted trusted header changed: %+v", q.headers["a"].trusted)
953		}
954	
955		// Empty root is still a valid input and compares as a raw string: on a
956		// fresh chain, two trusted headers at the same height with empty roots are
957		// idempotent, not a conflict.
958		q.RegisterSource("b")
959		if err := q.UpsertHeader(Header{Chain: "b", Height: 50, Root: "", Trusted: true}); err != nil {
960			t.Fatal(err)
961		}
962		if err := q.UpsertHeader(Header{Chain: "b", Height: 50, Root: "", Trusted: true}); err != nil {
963			t.Fatalf("same height same empty root must succeed: %v", err)
964		}
965		if q.headers["b"].trusted == nil || q.headers["b"].trusted.Height != 50 ||
966			q.headers["b"].trusted.Root != "" {
967			t.Fatalf("empty-root trusted header changed: %+v", q.headers["b"].trusted)
968		}
